import { useEffect, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

import DashboardCharts from "../components/charts/DashboardCharts";

function AdminDashboard() {

    const navigate = useNavigate();

    // ==========================================
    // STATE
    // ==========================================

    const [bookings, setBookings] = useState([]);

    const [payments, setPayments] = useState([]);

    const [dashboardData, setDashboardData] =
        useState({});

    const [searchText, setSearchText] =
        useState("");

    // ==========================================
    // CHART REF
    // ==========================================

    const chartSectionRef = useRef(null);

    const chartContentRef = useRef(null);

    // ==========================================
    // LOAD DATA
    // ==========================================

    useEffect(() => {

        fetchBookings();

        fetchDashboardData();

        fetchPayments();

    }, []);

    // ==========================================
    // FETCH BOOKINGS
    // ==========================================

    const fetchBookings = () => {

        axios
            .get(
                "http://localhost:8081/booking/all"
            )
            .then((response) => {

                if (
                    Array.isArray(
                        response.data
                    )
                ) {

                    setBookings(
                        response.data
                    );

                } else {

                    setBookings([]);

                }

            })
            .catch((error) => {

                console.error(
                    "Booking Error:",
                    error
                );

            });

    };

    // ==========================================
    // FETCH DASHBOARD DATA
    // ==========================================

    const fetchDashboardData = () => {

        axios
            .get(
                "http://localhost:8081/admin/dashboard"
            )
            .then((response) => {

                setDashboardData(
                    response.data || {}
                );

            })
            .catch((error) => {

                console.error(
                    "Dashboard Error:",
                    error
                );

            });

    };

    // ==========================================
    // FETCH PAYMENTS
    // ==========================================

    const fetchPayments = () => {

        axios
            .get(
                "http://localhost:8081/payment/all"
            )
            .then((response) => {

                if (
                    Array.isArray(
                        response.data
                    )
                ) {

                    setPayments(
                        response.data
                    );

                } else {

                    setPayments([]);

                }

            })
            .catch((error) => {

                console.error(
                    "Payment Error:",
                    error
                );

            });

    };

    // ==========================================
    // APPROVE BOOKING
    // ==========================================

    const approveBooking = (id) => {

        axios
            .put(
                `http://localhost:8081/booking/approve/${id}`
            )
            .then(() => {

                alert(
                    "Booking Approved"
                );

                fetchBookings();

                fetchDashboardData();

            })
            .catch((error) => {

                console.error(
                    "Approve Error:",
                    error
                );

                alert(
                    "Unable to approve booking."
                );

            });

    };

    // ==========================================
    // REJECT BOOKING
    // ==========================================

    const rejectBooking = (id) => {

        axios
            .put(
                `http://localhost:8081/booking/reject/${id}`
            )
            .then(() => {

                alert(
                    "Booking Rejected"
                );

                fetchBookings();

                fetchDashboardData();

            })
            .catch((error) => {

                console.error(
                    "Reject Error:",
                    error
                );

                alert(
                    "Unable to reject booking."
                );

            });

    };

    // ==========================================
    // SMOOTH CHART SCROLL EFFECT
    // ==========================================

    useEffect(() => {

        const handleScroll = () => {

            if (
                !chartSectionRef.current ||
                !chartContentRef.current
            ) {
                return;
            }

            const section =
                chartSectionRef.current;

            const chart =
                chartContentRef.current;

            const rect =
                section.getBoundingClientRect();

            const viewportHeight =
                window.innerHeight;

            /*
             * Chart starts small.
             *
             * 0.72 = starting scale
             * 1.00 = final medium scale
             */

            const startPoint =
                viewportHeight * 0.80;

            const endPoint =
                viewportHeight * 0.35;

            const distance =
                startPoint - endPoint;

            const progress =
                (startPoint - rect.top) /
                distance;

            const limitedProgress =
                Math.max(
                    0,
                    Math.min(
                        1,
                        progress
                    )
                );

            const scale =
                0.72 +
                (0.28 * limitedProgress);

            chart.style.transform =
                `scale(${scale})`;

        };

        handleScroll();

        window.addEventListener(
            "scroll",
            handleScroll,
            {
                passive: true
            }
        );

        window.addEventListener(
            "resize",
            handleScroll
        );

        return () => {

            window.removeEventListener(
                "scroll",
                handleScroll
            );

            window.removeEventListener(
                "resize",
                handleScroll
            );

        };

    }, []);

    // ==========================================
    // SORT BOOKINGS
    // ==========================================
    /*
     * Your current booking response does not expose
     * a creation timestamp.
     *
     * Therefore highest booking ID is used as the
     * newest record ordering.
     */

    const sortedBookings = [
        ...bookings
    ].sort(
        (a, b) =>
            Number(b.id || 0) -
            Number(a.id || 0)
    );

    // ==========================================
    // SORT PAYMENTS
    // ==========================================
    /*
     * Payment date is used when available.
     * ID is used as fallback.
     */

    const sortedPayments = [
        ...payments
    ].sort((a, b) => {

        const dateA =
            a.paymentDate
                ? new Date(
                    a.paymentDate
                ).getTime()
                : 0;

        const dateB =
            b.paymentDate
                ? new Date(
                    b.paymentDate
                ).getTime()
                : 0;

        if (
            dateA !== dateB
        ) {

            return dateB - dateA;

        }

        return (
            Number(b.id || 0) -
            Number(a.id || 0)
        );

    });

    // ==========================================
    // SEARCH BOOKINGS
    // ==========================================

    const filteredBookings =
        sortedBookings.filter(
            (booking) => {

                const customerName =
                    booking.customer &&
                    booking.customer.name
                        ? booking.customer.name
                        : "";

                const carName =
                    booking.carVariant &&
                    booking.carVariant.variantName
                        ? booking.carVariant.variantName
                        : "";

                const search =
                    searchText.toLowerCase();

                return (
                    customerName
                        .toLowerCase()
                        .includes(search)
                    ||
                    carName
                        .toLowerCase()
                        .includes(search)
                );

            }
        );

    // ==========================================
    // PAYMENT STATUS COLOR
    // ==========================================

    const getPaymentStatusColor =
        (status) => {

            if (
                status === "PAID"
            ) {
                return "green";
            }

            if (
                status === "FAILED"
            ) {
                return "red";
            }

            return "orange";

        };

    // ==========================================
    // BOOKING STATUS COLOR
    // ==========================================

    const getBookingStatusColor =
        (status) => {

            if (
                status === "APPROVED"
            ) {
                return "green";
            }

            if (
                status === "REJECTED"
            ) {
                return "red";
            }

            return "orange";

        };

    // ==========================================
    // PAGE
    // ==========================================

    return (

        <div
            style={{
                minHeight:
                    "100vh",
                backgroundColor:
                    "#f7f7f7",
                padding:
                    "30px"
            }}
        >

            {/* ==========================================
                PAGE TITLE
            ========================================== */}

            <div
                style={{
                    marginBottom:
                        "25px"
                }}
            >

                <h1
                    style={{
                        margin:
                            "0 0 20px 0",
                        fontSize:
                            "34px"
                    }}
                >
                    Admin Dashboard
                </h1>


                {/* ==========================================
                    MANAGEMENT BUTTONS
                ========================================== */}

                <div
                    style={{
                        display:
                            "flex",
                        flexWrap:
                            "wrap",
                        gap:
                            "15px"
                    }}
                >

                    <button
                        onClick={() =>
                            navigate(
                                "/manage-cars"
                            )
                        }
                        style={{
                            backgroundColor:
                                "black",
                            color:
                                "white",
                            border:
                                "none",
                            padding:
                                "12px 22px",
                            borderRadius:
                                "6px",
                            cursor:
                                "pointer",
                            fontSize:
                                "15px"
                        }}
                    >
                        🚗 Manage Cars
                    </button>


                    <button
                        onClick={() =>
                            navigate(
                                "/manage-reviews"
                            )
                        }
                        style={{
                            backgroundColor:
                                "#ff9800",
                            color:
                                "white",
                            border:
                                "none",
                            padding:
                                "12px 22px",
                            borderRadius:
                                "6px",
                            cursor:
                                "pointer",
                            fontSize:
                                "15px"
                        }}
                    >
                        ⭐ Manage Reviews
                    </button>

                </div>

            </div>


            {/* ==========================================
                SEARCH
            ========================================== */}

            <div
                style={{
                    marginBottom:
                        "25px"
                }}
            >

                <input
                    type="text"
                    placeholder=
                        "Search Customer or Car"
                    value={
                        searchText
                    }
                    onChange={(e) =>
                        setSearchText(
                            e.target.value
                        )
                    }
                    style={{
                        padding:
                            "12px 15px",
                        width:
                            "320px",
                        maxWidth:
                            "100%",
                        borderRadius:
                            "7px",
                        border:
                            "1px solid #bbb",
                        fontSize:
                            "15px",
                        outline:
                            "none"
                    }}
                />

            </div>


            {/* ==========================================
                STAT CARDS
            ========================================== */}

            <div
                style={{
                    display:
                        "grid",
                    gridTemplateColumns:
                        "repeat(4, minmax(160px, 1fr))",
                    gap:
                        "18px",
                    marginBottom:
                        "35px"
                }}
                className=
                    "admin-stat-grid"
            >

                {/* CUSTOMERS */}

                <div
                    style={{
                        backgroundColor:
                            "white",
                        padding:
                            "18px 20px",
                        minHeight:
                            "125px",
                        borderRadius:
                            "10px",
                        border:
                            "1px solid #e5e5e5",
                        boxShadow:
                            "0 2px 8px rgba(0,0,0,0.06)"
                    }}
                >

                    <p
                        style={{
                            margin:
                                "0 0 10px",
                            fontSize:
                                "17px",
                            fontWeight:
                                "600"
                        }}
                    >
                        Customers
                    </p>

                    <h2
                        style={{
                            margin:
                                "0",
                            fontSize:
                                "30px"
                        }}
                    >
                        {
                            dashboardData.totalCustomers ||
                            0
                        }
                    </h2>

                </div>


                {/* CARS */}

                <div
                    style={{
                        backgroundColor:
                            "white",
                        padding:
                            "18px 20px",
                        minHeight:
                            "125px",
                        borderRadius:
                            "10px",
                        border:
                            "1px solid #e5e5e5",
                        boxShadow:
                            "0 2px 8px rgba(0,0,0,0.06)"
                    }}
                >

                    <p
                        style={{
                            margin:
                                "0 0 10px",
                            fontSize:
                                "17px",
                            fontWeight:
                                "600"
                        }}
                    >
                        Cars
                    </p>

                    <h2
                        style={{
                            margin:
                                "0",
                            fontSize:
                                "30px"
                        }}
                    >
                        {
                            dashboardData.totalCars ||
                            0
                        }
                    </h2>

                </div>


                {/* BOOKINGS */}

                <div
                    style={{
                        backgroundColor:
                            "white",
                        padding:
                            "18px 20px",
                        minHeight:
                            "125px",
                        borderRadius:
                            "10px",
                        border:
                            "1px solid #e5e5e5",
                        boxShadow:
                            "0 2px 8px rgba(0,0,0,0.06)"
                    }}
                >

                    <p
                        style={{
                            margin:
                                "0 0 10px",
                            fontSize:
                                "17px",
                            fontWeight:
                                "600"
                        }}
                    >
                        Bookings
                    </p>

                    <h2
                        style={{
                            margin:
                                "0",
                            fontSize:
                                "30px"
                        }}
                    >
                        {
                            dashboardData.totalBookings ||
                            0
                        }
                    </h2>

                </div>


                {/* PAYMENTS */}

                <div
                    style={{
                        backgroundColor:
                            "white",
                        padding:
                            "18px 20px",
                        minHeight:
                            "125px",
                        borderRadius:
                            "10px",
                        border:
                            "1px solid #e5e5e5",
                        boxShadow:
                            "0 2px 8px rgba(0,0,0,0.06)"
                    }}
                >

                    <p
                        style={{
                            margin:
                                "0 0 10px",
                            fontSize:
                                "17px",
                            fontWeight:
                                "600"
                        }}
                    >
                        Payments
                    </p>

                    <h2
                        style={{
                            margin:
                                "0",
                            fontSize:
                                "30px"
                        }}
                    >
                        {
                            dashboardData.totalPayments ||
                            payments.length
                        }
                    </h2>

                </div>

            </div>


            {/* ==========================================
                CHART SCROLL AREA
            ========================================== */}

            <div
                ref={
                    chartSectionRef
                }
                style={{
                    height:
                        "520px",
                    position:
                        "relative",
                    marginBottom:
                        "30px"
                }}
                className=
                    "admin-chart-scroll-area"
            >

                <div
                    style={{
                        position:
                            "sticky",
                        top:
                            "15px",
                        display:
                            "flex",
                        justifyContent:
                            "center",
                        alignItems:
                            "flex-start",
                        height:
                            "420px",
                        overflow:
                            "visible"
                    }}
                >

                    <div
                        ref={
                            chartContentRef
                        }
                        style={{
                            width:
                                "100%",
                            maxWidth:
                                "1100px",
                            transform:
                                "scale(0.72)",
                            transformOrigin:
                                "center top",
                            transition:
                                "transform 0.08s linear",
                            willChange:
                                "transform"
                        }}
                        className=
                            "admin-chart-content"
                    >

                        <DashboardCharts
                            dashboardData={
                                dashboardData
                            }
                        />

                    </div>

                </div>

            </div>


            {/* ==========================================
                TWO MANAGEMENT SECTIONS
            ========================================== */}

            <div
                style={{
                    display:
                        "grid",
                    gridTemplateColumns:
                        "1fr 1fr",
                    gap:
                        "25px",
                    alignItems:
                        "start"
                }}
                className=
                    "admin-management-grid"
            >

                {/* ==================================================
                    BOOKING MANAGEMENT
                ================================================== */}

                <section
                    style={{
                        backgroundColor:
                            "white",
                        border:
                            "1px solid #e1e1e1",
                        borderRadius:
                            "10px",
                        padding:
                            "20px",
                        boxShadow:
                            "0 2px 8px rgba(0,0,0,0.05)"
                    }}
                >

                    <div
                        style={{
                            display:
                                "flex",
                            justifyContent:
                                "space-between",
                            alignItems:
                                "center",
                            marginBottom:
                                "20px",
                            gap:
                                "10px"
                        }}
                    >

                        <h2
                            style={{
                                margin:
                                    "0",
                                fontSize:
                                    "22px"
                            }}
                        >
                            Booking Management
                        </h2>

                        <span
                            style={{
                                backgroundColor:
                                    "#f1f1f1",
                                padding:
                                    "6px 10px",
                                borderRadius:
                                    "15px",
                                fontSize:
                                    "13px"
                            }}
                        >
                            Newest First
                        </span>

                    </div>


                    {/* ==========================================
                        BOOKING LIST
                    ========================================== */}

                    {
                        filteredBookings.length ===
                        0 ? (

                            <p
                                style={{
                                    color:
                                        "#777",
                                    textAlign:
                                        "center",
                                    padding:
                                        "30px"
                                }}
                            >
                                No bookings found.
                            </p>

                        ) : (

                            filteredBookings.map(
                                (booking) => (

                                    <div
                                        key={
                                            booking.id
                                        }
                                        style={{
                                            border:
                                                "1px solid #ddd",
                                            borderRadius:
                                                "8px",
                                            padding:
                                                "16px",
                                            marginBottom:
                                                "15px",
                                            backgroundColor:
                                                "#fafafa"
                                        }}
                                    >

                                        {/* CAR NAME */}

                                        <h3
                                            style={{
                                                margin:
                                                    "0 0 12px",
                                                fontSize:
                                                    "19px"
                                            }}
                                        >

                                            {
                                                booking.carVariant &&
                                                booking.carVariant.variantName
                                                    ? booking.carVariant.variantName
                                                    : "Car"
                                            }

                                            {
                                                booking.carVariant &&
                                                booking.carVariant.fuelType
                                                    ? ` - ${booking.carVariant.fuelType}`
                                                    : ""
                                            }

                                        </h3>


                                        {/* CUSTOMER */}

                                        <p
                                            style={{
                                                margin:
                                                    "7px 0"
                                            }}
                                        >

                                            <b>
                                                Customer:
                                            </b>

                                            {" "}

                                            {
                                                booking.customer &&
                                                booking.customer.name
                                                    ? booking.customer.name
                                                    : "No Customer"
                                            }

                                        </p>


                                        {/* EMAIL */}

                                        <p
                                            style={{
                                                margin:
                                                    "7px 0"
                                            }}
                                        >

                                            <b>
                                                Email:
                                            </b>

                                            {" "}

                                            {
                                                booking.customer &&
                                                booking.customer.email
                                                    ? booking.customer.email
                                                    : "Not Available"
                                            }

                                        </p>


                                        {/* FROM DATE */}

                                        <p
                                            style={{
                                                margin:
                                                    "7px 0"
                                            }}
                                        >

                                            <b>
                                                From Date:
                                            </b>

                                            {" "}

                                            {
                                                booking.fromDate ||
                                                "Not Available"
                                            }

                                        </p>


                                        {/* TO DATE */}

                                        <p
                                            style={{
                                                margin:
                                                    "7px 0"
                                            }}
                                        >

                                            <b>
                                                To Date:
                                            </b>

                                            {" "}

                                            {
                                                booking.toDate ||
                                                "Not Available"
                                            }

                                        </p>


                                        {/* TOTAL */}

                                        <p
                                            style={{
                                                margin:
                                                    "7px 0"
                                            }}
                                        >

                                            <b>
                                                Total Amount:
                                            </b>

                                            {" ₹"}

                                            {
                                                booking.totalAmount ||
                                                0
                                            }

                                        </p>


                                        {/* ASSIGNED CAR */}

                                        <p
                                            style={{
                                                margin:
                                                    "7px 0"
                                            }}
                                        >

                                            <b>
                                                Assigned Car:
                                            </b>

                                            {" "}

                                            {
                                                booking.car &&
                                                booking.car.registrationNumber
                                                    ? booking.car.registrationNumber
                                                    : "Not Assigned"
                                            }

                                        </p>


                                        {/* STATUS */}

                                        <p
                                            style={{
                                                margin:
                                                    "7px 0"
                                            }}
                                        >

                                            <b>
                                                Status:
                                            </b>

                                            {" "}

                                            <span
                                                style={{
                                                    color:
                                                        getBookingStatusColor(
                                                            booking.bookingStatus
                                                        ),
                                                    fontWeight:
                                                        "bold"
                                                }}
                                            >

                                                {
                                                    booking.bookingStatus ||
                                                    "PENDING"
                                                }

                                            </span>

                                        </p>


                                        {/* BOOKING ID */}

                                        <p
                                            style={{
                                                margin:
                                                    "7px 0"
                                            }}
                                        >

                                            <b>
                                                Booking ID:
                                            </b>

                                            {" "}

                                            {
                                                booking.id
                                            }

                                        </p>


                                        {/* BUTTONS */}

                                        <div
                                            style={{
                                                display:
                                                    "flex",
                                                gap:
                                                    "10px",
                                                marginTop:
                                                    "14px"
                                            }}
                                        >

                                            <button
                                                onClick={() =>
                                                    approveBooking(
                                                        booking.id
                                                    )
                                                }
                                                style={{
                                                    backgroundColor:
                                                        "green",
                                                    color:
                                                        "white",
                                                    border:
                                                        "none",
                                                    padding:
                                                        "9px 16px",
                                                    borderRadius:
                                                        "5px",
                                                    cursor:
                                                        "pointer"
                                                }}
                                            >
                                                Approve
                                            </button>


                                            <button
                                                onClick={() =>
                                                    rejectBooking(
                                                        booking.id
                                                    )
                                                }
                                                style={{
                                                    backgroundColor:
                                                        "red",
                                                    color:
                                                        "white",
                                                    border:
                                                        "none",
                                                    padding:
                                                        "9px 16px",
                                                    borderRadius:
                                                        "5px",
                                                    cursor:
                                                        "pointer"
                                                }}
                                            >
                                                Reject
                                            </button>

                                        </div>

                                    </div>

                                )
                            )

                        )
                    }

                </section>


                {/* ==================================================
                    PAYMENT MANAGEMENT
                ================================================== */}

                <section
                    style={{
                        backgroundColor:
                            "white",
                        border:
                            "1px solid #e1e1e1",
                        borderRadius:
                            "10px",
                        padding:
                            "20px",
                        boxShadow:
                            "0 2px 8px rgba(0,0,0,0.05)"
                    }}
                >

                    <div
                        style={{
                            display:
                                "flex",
                            justifyContent:
                                "space-between",
                            alignItems:
                                "center",
                            marginBottom:
                                "20px",
                            gap:
                                "10px"
                        }}
                    >

                        <h2
                            style={{
                                margin:
                                    "0",
                                fontSize:
                                    "22px"
                            }}
                        >
                            Payment Management
                        </h2>

                        <span
                            style={{
                                backgroundColor:
                                    "#f1f1f1",
                                padding:
                                    "6px 10px",
                                borderRadius:
                                    "15px",
                                fontSize:
                                    "13px"
                            }}
                        >
                            Newest First
                        </span>

                    </div>


                    {/* ==========================================
                        PAYMENT LIST
                    ========================================== */}

                    {
                        sortedPayments.length ===
                        0 ? (

                            <p
                                style={{
                                    color:
                                        "#777",
                                    textAlign:
                                        "center",
                                    padding:
                                        "30px"
                                }}
                            >
                                No payments found.
                            </p>

                        ) : (

                            sortedPayments.map(
                                (payment) => {

                                    const paymentBooking =
                                        payment.booking ||
                                        {};

                                    const paymentCustomer =
                                        payment.customer ||
                                        paymentBooking.customer ||
                                        {};

                                    const paymentCar =
                                        paymentBooking.carVariant ||
                                        {};

                                    return (

                                        <div
                                            key={
                                                payment.id
                                            }
                                            style={{
                                                border:
                                                    "1px solid #ddd",
                                                borderRadius:
                                                    "8px",
                                                padding:
                                                    "16px",
                                                marginBottom:
                                                    "15px",
                                                backgroundColor:
                                                    "#fafafa"
                                            }}
                                        >

                                            {/* PAYMENT ID */}

                                            <h3
                                                style={{
                                                    margin:
                                                        "0 0 12px",
                                                    fontSize:
                                                        "19px"
                                                }}
                                            >
                                                Payment #
                                                {" "}
                                                {
                                                    payment.id
                                                }
                                            </h3>


                                            {/* AMOUNT */}

                                            <p
                                                style={{
                                                    margin:
                                                        "7px 0"
                                                }}
                                            >

                                                <b>
                                                    Amount:
                                                </b>

                                                {" ₹"}

                                                {
                                                    payment.amount ||
                                                    0
                                                }

                                            </p>


                                            {/* PAYMENT STATUS */}

                                            <p
                                                style={{
                                                    margin:
                                                        "7px 0"
                                                }}
                                            >

                                                <b>
                                                    Payment Status:
                                                </b>

                                                {" "}

                                                <span
                                                    style={{
                                                        color:
                                                            getPaymentStatusColor(
                                                                payment.paymentStatus
                                                            ),
                                                        fontWeight:
                                                            "bold"
                                                    }}
                                                >

                                                    {
                                                        payment.paymentStatus ||
                                                        "UNKNOWN"
                                                    }

                                                </span>

                                            </p>


                                            {/* PAYMENT DATE */}

                                            <p
                                                style={{
                                                    margin:
                                                        "7px 0"
                                                }}
                                            >

                                                <b>
                                                    Payment Date:
                                                </b>

                                                {" "}

                                                {
                                                    payment.paymentDate ||
                                                    "Not Available"
                                                }

                                            </p>


                                            {/* BOOKING ID */}

                                            <p
                                                style={{
                                                    margin:
                                                        "7px 0"
                                                }}
                                            >

                                                <b>
                                                    Booking ID:
                                                </b>

                                                {" "}

                                                {
                                                    paymentBooking.id ||
                                                    "Not Available"
                                                }

                                            </p>


                                            {/* BOOKING STATUS */}

                                            <p
                                                style={{
                                                    margin:
                                                        "7px 0"
                                                }}
                                            >

                                                <b>
                                                    Booking Status:
                                                </b>

                                                {" "}

                                                {
                                                    paymentBooking.bookingStatus ||
                                                    "Not Available"
                                                }

                                            </p>


                                            {/* CUSTOMER */}

                                            <p
                                                style={{
                                                    margin:
                                                        "7px 0"
                                                }}
                                            >

                                                <b>
                                                    Customer:
                                                </b>

                                                {" "}

                                                {
                                                    paymentCustomer.name ||
                                                    "Not Available"
                                                }

                                            </p>


                                            {/* CAR */}

                                            <p
                                                style={{
                                                    margin:
                                                        "7px 0"
                                                }}
                                            >

                                                <b>
                                                    Car:
                                                </b>

                                                {" "}

                                                {
                                                    paymentCar.variantName ||
                                                    "Not Available"
                                                }

                                            </p>


                                            {/* PAYMENT ID */}

                                            <p
                                                style={{
                                                    margin:
                                                        "7px 0"
                                                }}
                                            >

                                                <b>
                                                    Payment ID:
                                                </b>

                                                {" "}

                                                {
                                                    payment.id
                                                }

                                            </p>

                                        </div>

                                    );

                                }

                            )

                        )
                    }

                </section>

            </div>


            {/* ==========================================
                RESPONSIVE CSS
            ========================================== */}

            <style>
                {`

                .admin-stat-grid {
                    width: 100%;
                }

                .admin-management-grid {
                    width: 100%;
                }

                .admin-chart-content {
                    overflow: visible;
                }

                @media (max-width: 900px) {

                    .admin-stat-grid {
                        grid-template-columns:
                            repeat(2, minmax(150px, 1fr)) !important;
                    }

                    .admin-management-grid {
                        grid-template-columns:
                            1fr !important;
                    }

                    .admin-chart-scroll-area {
                        height: 500px !important;
                    }

                }

                @media (max-width: 600px) {

                    .admin-stat-grid {
                        grid-template-columns:
                            1fr 1fr !important;
                        gap: 10px !important;
                    }

                    .admin-chart-scroll-area {
                        height: 450px !important;
                    }

                    .admin-chart-content {
                        width: 115% !important;
                        margin-left: -7.5%;
                    }

                }

                @media (prefers-reduced-motion: reduce) {

                    .admin-chart-content {
                        transform: scale(0.9) !important;
                        transition: none !important;
                    }

                }

                `}
            </style>

        </div>

    );

}

export default AdminDashboard;
